jQuery( document ).ready( function( $ ) {
	/**
	 * Change handler for options - Reset Save status.
	 */
	$( document ).on( 'change', '.wpmozo_bna_panel_section .wpmozo_bna_panel_value', function() {
		const $section = $(this).closest( '.wpmozo_bna_panel_section' );
		const $saveBox = $section.find( '.wpmozo_bna_panel_save_options' );
		const saveText = $saveBox.find( '.wpmozo_bna_panel_save_text' ).data( 'text' );

		$saveBox.removeClass( 'success error' );
		$saveBox.find( '.wpmozo_bna_panel_save_text' ).text( saveText );
	} );

	/**
	 * On click of block checkbox,
	 * reset values & update the values in hidden field.
	 */
	$( document ).on( 'click', '.wpmozo_bna_panel_checkbox, .wpmozo_toggle_slider', function (e) {
		let $checkbox;

		if ( $(this).hasClass( 'wpmozo_toggle_slider' ) ) {
			// Toggle slider clicked — find related checkbox and toggle it.
			$checkbox = $(this).prev( '.wpmozo_bna_panel_checkbox' );
			const isChecked = $checkbox.is( ':checked' );
			$checkbox.prop( 'checked', !isChecked );
		} else {
			// Checkbox directly clicked.
			$checkbox = $(this);
		}

		const $container = $checkbox.closest( '.wpmozo_bna_panel_multiple_checkbox' );
		const $section   = $checkbox.closest( '.wpmozo_bna_panel_section' );
		const $saveBox   = $section.find( '.wpmozo_bna_panel_save_options' );
		const saveText   = $saveBox.find( '.wpmozo_bna_panel_save_text' ).data( 'text' );

		const selected = $container.find( '.wpmozo_bna_panel_checkbox:checked' ).map( function () {
			return $(this).val();
		} ).get();
		const all = $container.find( '.wpmozo_bna_panel_checkbox' ).map( function () {
			if ( ! $( this ).prop( 'disabled' ) ) {
				return $( this ).val();
			}
		} ).get();

		const unselected = all.filter( val => !selected.includes( val ) );

		$container.find( '.wpmozo_active_checkboxes_value' ).val( selected );
		$container.find( '.wpmozo_inactive_checkboxes_value' ).val( unselected );

		$saveBox.removeClass( 'success error' );
		$saveBox.find( '.wpmozo_bna_panel_save_text' ).text( saveText );
	} );

	$( 'body .wpmozo_bna_panel_wrapper:not(.proactive) .wpmozo_pro' ).each( function () {
		$(this).find( '.wpmozo_bna_panel_checkbox' ).prop( 'disabled', true );
		$(this).find( '.wpmozo_toggle_slider' ).prop( 'disabled', true );
	} );

	/**
	 * Save settings
	 */
	$( document ).on( 'click', '.wpmozo_bna_panel_save_options', function (e) {
		e.preventDefault();
		const $button    = $(this);
		const $section   = $button.closest( '.wpmozo_bna_panel_active_section' );

		if ( $button.hasClass( 'success' ) || $button.hasClass( 'error' ) ) {
			return false;
		}

		$( '.wpmozo_bna_panel_ajax_processor' ).fadeIn( 'slow' );

		const options = [];
		$section.find( '#wpmozo_inactive_blocks' ).each( function () {
			const name  = $(this).attr( 'name' );
			const value = $(this).val();
			options.push( { name, value } );
		} );

		$.ajax({
			type: "POST",
			url: WPMozoPanel.ajaxurl,
			data: {
				action: 'wpmozo_bna_panel_save_settings',
				security: WPMozoPanel.ajax_nonce,
				options: options
			},
			success: function ( response ) {
				// console.log(response);
				if ( response === 'success') {
					$button.find( '.wpmozo_ae_panel_save_text' ).text( 'Saved' );
					$button.addClass( 'success' );
					setTimeout( function () {
						$( '.wpmozo_bna_panel_ajax_processor' ).fadeOut( 'slow' );
					}, 800 );
				}
			},
			error: function (error) {
				console.error( error );
				alert( 'Oops!! Something went wrong!! Try later!' );
				$button.addClass( 'error' );
				setTimeout( function () {
					$( '.wpmozo_bna_panel_ajax_processor' ).fadeOut( 'slow' );
				}, 800 );
			}
		} );
	} );

	/**
	 * Select all checkboxes.
	 */
	$( document ).on( 'click', '.wpmozo_bna_panel_select_all', function () {
		const $container = $(this).closest( '.wpmozo_bna_panel_multiple_checkbox' );
		const $section   = $(this).closest( '.wpmozo_bna_panel_section' );
		const saveText   = $section.find( '.wpmozo_bna_panel_save_text' ).data( 'text' );
		
		let selected;
		$section.find( '.wpmozo_bna_panel_save_options' ).removeClass( 'success error' )
			.find( '.wpmozo_bna_panel_save_text' ).text( saveText );

		if ( $container.closest( '.wpmozo_bna_panel_wrapper.proactive' ).length ) {
			$container.find( "input[type='checkbox']" ).prop( 'checked', true );
			selected = $container.find( '.wpmozo_bna_panel_checkbox:checked' ).map( function () {
				return $(this).val();
			} ).get();
		} else {
			$container.find( ".wpmozo_bna_checkbox_wrapper:not(.wpmozo_pro) input[type='checkbox']" ).prop( 'checked', true );
			selected = $container.find( ".wpmozo_bna_checkbox_wrapper:not(.wpmozo_pro) .wpmozo_bna_panel_checkbox:checked" ).map( function () {
				return $(this).val();
			} ).get();
		}

		$container.find( '.wpmozo_inactive_checkboxes_value.wpmozo_panel_value' ).val( "" );
		$container.find( '.wpmozo_active_checkboxes_value.wpmozo_panel_value' ).val( selected );
	} );

	/**
	 * Deselect all checkboxes
	 */
	$( document ).on( 'click', '.wpmozo_bna_panel_deselect_all', function () {
		const $container = $(this).closest( '.wpmozo_bna_panel_multiple_checkbox' );
		const $section   = $(this).closest( '.wpmozo_bna_panel_section' );
		const saveText   = $section.find( '.wpmozo_bna_panel_save_text' ).data( 'text' );
		
		let all;
		$section.find( '.wpmozo_bna_panel_save_options' ).removeClass( 'success error' )
			.find( '.wpmozo_bna_panel_save_text' ).text( saveText );


		if ( $container.closest('.wpmozo_bna_panel_wrapper.proactive').length ) {
			$container.find( "input[type='checkbox']").prop( 'checked', false );
			all = $container.find( '.wpmozo_bna_panel_checkbox' ).map( function () {
				return $(this).val();
			} ).get();
		} else {
			$container.find( ".wpmozo_bna_checkbox_wrapper:not(.wpmozo_pro) input[type='checkbox']" ).prop( 'checked', false );
			all = $container.find( '.wpmozo_bna_checkbox_wrapper:not(.wpmozo_pro) .wpmozo_bna_panel_checkbox' ).map( function () {
				return $(this).val();
			} ).get();
		}

		$container.find( '.wpmozo_inactive_checkboxes_value.wpmozo_panel_value' ).val( all );
		$container.find( '.wpmozo_active_checkboxes_value.wpmozo_panel_value' ).val( "" );
	} );

	/**
	 * Handle menu item navigation
	 */
	$( document ).on( 'click', '.wpmozo_bna_panel_menu_item', function () {
		const $this = $( this );
		if ( $this.hasClass( 'wpmozo_bna_panel_active_menu_item' ) ) return false;

		const sectionId      = $this.data( 'href' );
		const $targetSection = $( sectionId );
		const saveText       = $( '.wpmozo_bna_panel_save_text' ).data( 'text' );

		$( '.wpmozo_bna_panel_menu_item' ).removeClass( 'wpmozo_bna_panel_active_menu_item' );
		$this.addClass( 'wpmozo_bna_panel_active_menu_item' );

		$( '.wpmozo_bna_panel_section' ).removeClass( 'wpmozo_bna_panel_active_section' );
		$targetSection.addClass( 'wpmozo_bna_panel_active_section' );

		$( '.wpmozo_bna_panel_save_options' ).removeClass( 'success error' )
			.find( '.wpmozo_bna_panel_save_text' ).text( saveText );
	} );
} ); // Document ready.
